const searchPublishedPosts = `-- name: SearchPublishedPosts :many
select
    p.id,
    p.slug,
    p.title,
    p.excerpt,
    p.published_at,
    u.display_name as author_name,
    c.slug as category_slug,
    c.name as category_name
from posts p
join users u on u.id = p.author_id
left join categories c on c.id = p.category_id
where p.deleted_at is null
  and p.status = 'published'
  and (p.title ilike $1 or p.excerpt ilike $1)
order by p.published_at desc nulls last, p.id desc
limit $2
`

type SearchPublishedPostsParams struct {
	Pattern string `json:"pattern"`
	Lim     int32  `json:"lim"`
}

type SearchPublishedPostsRow struct {
	ID           int64      `json:"id"`
	Slug         string     `json:"slug"`
	Title        string     `json:"title"`
	Excerpt      string     `json:"excerpt"`
	PublishedAt  *time.Time `json:"published_at"`
	AuthorName   string     `json:"author_name"`
	CategorySlug *string    `json:"category_slug"`
	CategoryName *string    `json:"category_name"`
}

func (q *Queries) SearchPublishedPosts(ctx context.Context, arg SearchPublishedPostsParams) ([]SearchPublishedPostsRow, error) {
	rows, err := q.db.Query(ctx, searchPublishedPosts, arg.Pattern, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchPublishedPostsRow{}
	for rows.Next() {
		var i SearchPublishedPostsRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Title,
			&i.Excerpt,
			&i.PublishedAt,
			&i.AuthorName,
			&i.CategorySlug,
			&i.CategoryName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const softDeletePost = `-- name: SoftDeletePost :execrows
update posts
set deleted_at = now(), updated_at = now()
where id = $1 and deleted_at is null
`

func (q *Queries) SoftDeletePost(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.Exec(ctx, softDeletePost, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

